(function() {
        var wrapperId = 'mct-dyn-6a8bf2fea844b';
        function fetchMacityWidget() {
            var request = new XMLHttpRequest();
            request.open('GET', '/wp-json/macity/v1/mct-widget', true);
            request.onload = function() {
                if (request.status >= 200 && request.status < 400) {
                    try {
                        var data = JSON.parse(request.responseText);
                        var container = document.getElementById(wrapperId);
                        if (container && data.html) {
                            // 1. Inietta subito la grafica (il browser disegna il banner)
                            container.innerHTML = data.html;

                            // 2. Raccoglie gli script di ASA2
                            var scripts = container.getElementsByTagName('script');
                            var scriptsCode = [];
                            for (var n = 0; n < scripts.length; n++) {
                                if (scripts[n].text) {
                                    scriptsCode.push(scripts[n].text);
                                }
                            }

                            // 3. Funzione di esecuzione ritardata (aspetta WP Rocket)
                            function executeScriptsWhenReady() {
                                if (scriptsCode.length === 0) return;

                                // Se jQuery non è ancora stato caricato da WP Rocket, aspetta 100 millisecondi e riprova
                                if (typeof jQuery === 'undefined') {
                                    setTimeout(executeScriptsWhenReady, 100);
                                    return;
                                }

                                // Quando jQuery è finalmente disponibile, eseguiamo gli script
                                for (var i = 0; i < scriptsCode.length; i++) {
                                    var s = document.createElement('script');
                                    s.text = scriptsCode[i];
                                    document.body.appendChild(s);
                                }
                            }

                            // Fa partire il controllo
                            executeScriptsWhenReady();
                        }
                    } catch (e) {}
                }
            };
            request.send();
        }

fetchMacityWidget(); 
